package com.example.eac_backend_project.transport;
import com.fasterxml.jackson.databind.JsonNode;
import com.example.eac_backend_project.entity.inventory.User;
import com.example.eac_backend_project.entity.transport.Vehicles;
import com.example.eac_backend_project.repository.UserRepository;
import com.example.eac_backend_project.repository.transport.VehicleRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.beans.factory.annotation.Autowired;
import java.time.*;
import java.math.*;
import java.util.*;
import static com.example.eac_backend_project.transport.TransportValues.*;
import static com.example.eac_backend_project.transport.TransportAccess.fail;

@Service @Transactional
public class TransportProcurementService {
 @Autowired TransportProcurements requests;
 @Autowired TransportProcurementItems items;
 @Autowired TransportPartReceipts receipts;
 @Autowired TransportFaults faults;
 @Autowired TransportWorkOrders orders;
 @Autowired TransportAccess access;
 @Autowired TransportCoreService core;
 @Autowired TransportAlerts alerts;
 @Autowired TransportWorkflows workflows;
 @Autowired VehicleRepository vehicles;
 @Autowired UserRepository users;
 @Autowired TransportPolicyService policy;
 boolean visible(TransportProcurement request,User user){return request.archivedAt==null&&(access.admin(user)||access.allows(user,"TRANSPORT_APPROVE_PROCUREMENT")||access.allows(user,"TRANSPORT_REPORTS")||request.requestedBy.getId().equals(user.getId())||request.assignedTo!=null&&request.assignedTo.getId().equals(user.getId()));}
 boolean purchaser(TransportProcurement request,User user){return access.admin(user)||access.procurement(user)&&request.assignedTo!=null&&request.assignedTo.getId().equals(user.getId());}
 TransportProcurement request(Long id){TransportProcurement r=requests.findById(id).filter(x->x.archivedAt==null).orElseThrow(()->fail(404,"Procurement request unavailable"));if(!visible(r,access.current()))throw fail(403,"This procurement request is not assigned or accessible to you");return r;}
 TransportProcurement lock(Long id){TransportProcurement r=request(id);vehicles.lock(r.vehicle.getId()).orElseThrow();return requests.lock(id).orElseThrow();}
 Map<String,Object> describe(TransportProcurement r){Map<String,Object> out=row(r);BigDecimal estimated=BigDecimal.ZERO,actual=BigDecimal.ZERO;List<Map<String,Object>> lines=new ArrayList<>();for(TransportProcurementItem item:items.findByRequest_Id(r.id).stream().filter(i->i.archivedAt==null).toList()){BigDecimal estimate=item.quantity.multiply(money(item.estimatedUnitCost));estimated=estimated.add(estimate);lines.add(map("id",item.id,"name",item.name,"unit",item.unit,"quantity",item.quantity,"estimatedUnitCost",item.estimatedUnitCost,"estimatedTotal",money(estimate),"receivedQuantity",item.receivedQuantity,"actualUnitCost",item.actualUnitCost));}List<Map<String,Object>> received=new ArrayList<>();for(TransportPartReceipt receipt:receipts.findByRequest_Id(r.id)){BigDecimal total=receipt.quantity.multiply(receipt.unitCost);actual=actual.add(total);received.add(map("id",receipt.id,"itemId",receipt.item.id,"item",receipt.item.name,"quantity",receipt.quantity,"unitCost",receipt.unitCost,"totalCost",money(total),"receivedDate",receipt.receivedDate,"receivedBy",receipt.receivedBy.getName(),"reference",receipt.reference));}out.putAll(map("vehicleId",r.vehicle.getId(),"vehicle",r.vehicle.getDvla(),"vehicleName",r.vehicle.getName(),"reference",r.reference,"category",r.category,"faultId",r.fault==null?null:r.fault.id,"faultReference",r.fault==null?null:r.fault.reference,"workOrderId",r.workOrder==null?null:r.workOrder.id,"workOrderReference",r.workOrder==null?null:r.workOrder.reference,"requestedBy",r.requestedBy.getName(),"requestedById",r.requestedBy.getId(),"assignedToId",r.assignedTo==null?null:r.assignedTo.getId(),"assignedTo",r.assignedTo==null?null:r.assignedTo.getName(),"approvedBy",r.approvedBy==null?null:r.approvedBy.getName(),"status",r.status,"priority",r.priority,"requestDate",r.requestDate,"requiredDate",r.requiredDate,"justification",r.justification,"reviewNotes",r.reviewNotes,"purchaseReference",r.purchaseReference,"supplier",r.supplier,"approvedAt",r.approvedAt,"receivedAt",r.receivedAt,"estimatedTotal",money(estimated),"actualTotal",money(actual),"items",lines,"receipts",received));return out;}
 public List<Map<String,Object>> list(Long vehicleId){User user=access.current();return requests.findByArchivedAtIsNullOrderByCreatedAtDesc().stream().filter(r->visible(r,user)&&(vehicleId==null||r.vehicle.getId().equals(vehicleId))).map(this::describe).toList();}
 public Map<String,Object> get(Long id){return describe(request(id));}
 public Map<String,Object> save(Long id,JsonNode data,String requestKey){core.lockedVehicle(id(data,"vehicleId",true));User user=access.current();if(!access.allows(user,"TRANSPORT_MANAGE_MAINTENANCE")&&!access.allows(user,"TRANSPORT_APPROVE_PROCUREMENT"))throw fail(403,"Transport maintenance or procurement approval permission required");String key=id==null?workflows.key(requestKey):null;if(id==null){var old=requests.findByRequestKey(key);if(old.isPresent()){if(!old.get().requestedBy.getId().equals(user.getId())||!Objects.equals(old.get().requestHash,workflows.fingerprint(data)))throw fail(409,"Idempotency-Key was already used for another request");return describe(old.get());}}
  Vehicles vehicle=core.lockedVehicle(id(data,"vehicleId",true));TransportProcurement r=id==null?new TransportProcurement():requests.lock(id).orElseThrow(()->fail(404,"Procurement request unavailable"));if(id!=null){if(!visible(r,user)||!r.vehicle.getId().equals(vehicle.getId()))throw fail(403,"Request is outside your access");revision(r,data);if(!"DRAFT".equals(r.status))throw fail(409,"Only draft requests may be edited");}r.vehicle=vehicle;r.requestedBy=r.requestedBy==null?user:r.requestedBy;r.createdBy=r.createdBy==null?user:r.createdBy;if(data.has("category")){String category=text(data,"category",100,false);if(category!=null&&!Objects.equals(category,r.category)&&!TransportPolicyService.split(policy.policy().procurementCategories).contains(category))throw fail(400,"Choose a configured request category");r.category=category;}else if(id==null)r.category=TransportPolicyService.split(policy.policy().procurementCategories).stream().findFirst().orElse(null);r.priority=choice(data,"priority",Set.of("LOW","MEDIUM","HIGH","CRITICAL"),"MEDIUM");r.requestDate=r.requestDate==null?today():r.requestDate;r.requiredDate=date(data,"requiredDate",false);if(r.requiredDate!=null&&r.requiredDate.isBefore(r.requestDate))throw fail(400,"Required date cannot precede the request date");r.justification=text(data,"justification",4000,true);
  Long faultId=id(data,"faultId",false);if(faultId!=null){r.fault=faults.findById(faultId).orElseThrow(()->fail(404,"Fault unavailable"));if(!r.fault.vehicle.getId().equals(vehicle.getId()))throw fail(400,"Fault belongs to another vehicle");}
  Long orderId=id(data,"workOrderId",false);if(orderId!=null){r.workOrder=orders.findById(orderId).orElseThrow(()->fail(404,"Work order unavailable"));if(!r.workOrder.vehicle.getId().equals(vehicle.getId())||Set.of("COMPLETED","CANCELLED").contains(r.workOrder.status))throw fail(409,"Choose an active work order for this vehicle");if(r.fault==null)r.fault=r.workOrder.fault;}
  Long assignee=id(data,"assignedToId",false);if(assignee!=null){User assigned=users.findById(assignee).filter(u->Boolean.TRUE.equals(u.getEnabled())).orElseThrow(()->fail(404,"Procurement account unavailable"));if(!access.procurement(assigned))throw fail(400,"Assign an account with procurement permission");r.assignedTo=assigned;}
  JsonNode lines=data.path("items");if(!lines.isArray()||lines.isEmpty()||lines.size()>100)throw fail(400,"Include between one and 100 requested parts");if(id==null){r.requestKey=key;r.requestHash=workflows.fingerprint(data);}requests.saveAndFlush(r);if(r.reference==null)r.reference="PR-"+String.format("%06d",r.id);
  if(id!=null)items.findByRequest_Id(r.id).forEach(item->item.archivedAt=Instant.now());for(JsonNode line:lines){TransportProcurementItem item=new TransportProcurementItem();item.request=r;item.name=text(line,"name",180,true);item.unit=text(line,"unit",40,true);item.quantity=number(line,"quantity",true,true);item.estimatedUnitCost=money(number(line,"estimatedUnitCost",true,false));item.receivedQuantity=BigDecimal.ZERO;item.createdBy=user;items.save(item);}core.audit(vehicle,id==null?"PROCUREMENT_DRAFT_CREATED":"PROCUREMENT_DRAFT_UPDATED",r.justification,r.reference);requests.saveAndFlush(r);return describe(r);}
 public Map<String,Object> transition(Long id,JsonNode data){TransportProcurement r=lock(id);User user=access.current();revision(r,data);String target=choice(data,"status",Set.of("PENDING_APPROVAL","APPROVED","REJECTED","SENT_TO_PROCUREMENT","PURCHASING","CANCELLED"),null);String notes=text(data,"reviewNotes",2000,false);
  if("PENDING_APPROVAL".equals(target)){if(!"DRAFT".equals(r.status)||!r.requestedBy.getId().equals(user.getId())&&!access.admin(user)&&!access.allows(user,"TRANSPORT_APPROVE_PROCUREMENT"))throw fail(409,"Only an authorized draft may be submitted");if(r.workOrder!=null){if(Set.of("COMPLETED","CANCELLED").contains(r.workOrder.status))throw fail(409,"Completed work cannot request more parts");r.workOrder.status="AWAITING_PARTS";if(r.workOrder.fault!=null)r.workOrder.fault.status="AWAITING_PARTS";}}
  else if(Set.of("APPROVED","REJECTED").contains(target)){access.require("TRANSPORT_APPROVE_PROCUREMENT");if(!"PENDING_APPROVAL".equals(r.status))throw fail(409,"Only pending requests may be approved or rejected");if("REJECTED".equals(target)&&(notes==null||notes.length()<10))throw fail(400,"Record a reason before rejecting the request");if("APPROVED".equals(target)){r.approvedBy=user;r.approvedAt=Instant.now();}}
  else if("SENT_TO_PROCUREMENT".equals(target)){access.require("TRANSPORT_APPROVE_PROCUREMENT");if(!"APPROVED".equals(r.status))throw fail(409,"Approve the request before sending it for purchase");Long assignee=id(data,"assignedToId",true);User assigned=users.findById(assignee).filter(u->Boolean.TRUE.equals(u.getEnabled())).orElseThrow(()->fail(404,"Procurement account unavailable"));if(!access.procurement(assigned))throw fail(400,"Assign an authorized procurement account");r.assignedTo=assigned;}
  else if("PURCHASING".equals(target)){if(!purchaser(r,user)||!"SENT_TO_PROCUREMENT".equals(r.status))throw fail(403,"Only the assigned procurement officer may start an approved purchase");r.purchaseReference=text(data,"purchaseReference",180,true);r.supplier=text(data,"supplier",180,true);}
  else{if(!access.allows(user,"TRANSPORT_APPROVE_PROCUREMENT")&&!"DRAFT".equals(r.status))throw fail(403,"Approval permission is required to cancel submitted procurement");if("DRAFT".equals(r.status)&&!r.requestedBy.getId().equals(user.getId())&&!access.admin(user))throw fail(403,"Only your own draft may be cancelled");if(Set.of("RECEIVED","PARTIALLY_RECEIVED","CANCELLED").contains(r.status))throw fail(409,"Received parts cannot be cancelled or erased");notes=text(data,"reviewNotes",2000,true);if(notes.length()<10)throw fail(400,"Record a cancellation reason");}
  r.status=target;r.reviewNotes=notes;requests.saveAndFlush(r);resumeIfResolved(r);core.audit(r.vehicle,"PROCUREMENT_"+target,Objects.toString(notes,r.justification),r.reference);alerts.event(r.vehicle,"PROCUREMENT_"+target,"Parts request "+target.toLowerCase(Locale.ROOT),r.justification,r.reference,"/transport/procurement?record="+r.id,"procurement:"+r.id+":"+target+":"+r.revision,r.assignedTo==null?List.of():List.of(r.assignedTo));return describe(r);}
 private void resumeIfResolved(TransportProcurement r){if(r.workOrder==null||!Set.of("RECEIVED","REJECTED","CANCELLED").contains(r.status))return;boolean waiting=requests.findByVehicle_IdAndArchivedAtIsNull(r.vehicle.getId()).stream().filter(other->other.workOrder!=null&&other.workOrder.id.equals(r.workOrder.id)).anyMatch(other->!Set.of("RECEIVED","REJECTED","CANCELLED").contains(other.status));if(!waiting&&"AWAITING_PARTS".equals(r.workOrder.status)){r.workOrder.status="SCHEDULED";if(r.workOrder.fault!=null)r.workOrder.fault.status="SCHEDULED";}}
 public Map<String,Object> receive(Long id,JsonNode data,String requestKey){TransportProcurement r=lock(id);User user=access.current();if(!purchaser(r,user))throw fail(403,"Parts receipt is restricted to the assigned procurement officer");String key=workflows.key(requestKey);String fingerprint=workflows.fingerprint(data);List<TransportPartReceipt> previous=receipts.findByBatchKey(key);if(!previous.isEmpty()){if(previous.stream().anyMatch(receipt->!receipt.request.id.equals(id)||!receipt.receivedBy.getId().equals(user.getId())||!Objects.equals(receipt.requestHash,fingerprint)))throw fail(409,"Idempotency-Key was used for a different delivery");return describe(r);}revision(r,data);if(!Set.of("PURCHASING","PARTIALLY_RECEIVED").contains(r.status))throw fail(409,"Only an approved purchase in progress may receive parts");LocalDate date=date(data,"receivedDate",true);if(date.isAfter(today())||date.isBefore(r.requestDate))throw fail(400,"Receipt date must be between the request date and today");String reference=text(data,"reference",180,true);JsonNode lines=data.path("items");if(!lines.isArray()||lines.isEmpty()||lines.size()>100)throw fail(400,"Include the delivered parts");Set<Long> seen=new HashSet<>();Map<Long,TransportProcurementItem> allowed=new HashMap<>();items.findByRequest_Id(r.id).stream().filter(item->item.archivedAt==null).forEach(item->allowed.put(item.id,item));
  for(JsonNode line:lines){Long itemId=id(line,"itemId",true);TransportProcurementItem item=allowed.get(itemId);if(item==null||!seen.add(itemId))throw fail(400,"Parts must belong to this request and appear once");BigDecimal quantity=number(line,"quantity",true,true),cost=money(number(line,"unitCost",true,false));BigDecimal received=item.receivedQuantity==null?BigDecimal.ZERO:item.receivedQuantity;if(received.add(quantity).compareTo(item.quantity)>0)throw fail(409,"Delivered quantity exceeds the requested balance for "+item.name);TransportPartReceipt receipt=new TransportPartReceipt();receipt.request=r;receipt.item=item;receipt.receivedBy=user;receipt.createdBy=user;receipt.quantity=quantity;receipt.unitCost=cost;receipt.receivedDate=date;receipt.reference=reference;receipt.requestKey=hash(key+":"+itemId);receipt.batchKey=key;receipt.requestHash=fingerprint;receipts.save(receipt);item.receivedQuantity=received.add(quantity);BigDecimal actual=receipts.findByRequest_Id(r.id).stream().filter(value->value.item.id.equals(item.id)).map(value->value.quantity.multiply(value.unitCost)).reduce(BigDecimal.ZERO,BigDecimal::add);item.actualUnitCost=actual.divide(item.receivedQuantity,2,RoundingMode.HALF_UP);}
  r.status=allowed.values().stream().allMatch(item->item.receivedQuantity!=null&&item.receivedQuantity.compareTo(item.quantity)>=0)?"RECEIVED":"PARTIALLY_RECEIVED";if("RECEIVED".equals(r.status))r.receivedAt=Instant.now();requests.saveAndFlush(r);resumeIfResolved(r);core.audit(r.vehicle,"PROCUREMENT_"+r.status,"Parts delivery recorded: "+reference,r.reference);alerts.event(r.vehicle,"PROCUREMENT_"+r.status,"Parts "+r.status.toLowerCase(Locale.ROOT),"Delivery "+reference+" has been recorded.",r.reference,"/transport/procurement?record="+r.id,"receipt:"+key,List.of(r.requestedBy));return describe(r);}
 public List<Map<String,Object>> officers(){User user=access.current();if(!access.allows(user,"TRANSPORT_APPROVE_PROCUREMENT")&&!access.allows(user,"TRANSPORT_MANAGE_MAINTENANCE"))throw fail(403,"Transport procurement access required");return users.findByEnabledTrue().stream().filter(access::procurement).map(u->map("id",u.getId(),"name",u.getName())).toList();}
}
